class TestFiles final : public raising_player::PortableSaveFilesBackend {
 public:
  fs::path root;bool active=false;uint64_t request=0,serial=0;
  raising_player::PortableSaveKind kind=raising_player::PortableSaveKind::import_file;
  std::deque<raising_player::PortableSaveResult> results;std::string exported;
  explicit TestFiles(fs::path p):root(std::move(p)){}
  bool available() const override{return true;}
  bool busy() const override{return active;}
  bool begin_import(uint64_t id) override{if(active)return false;active=true;request=id;kind=raising_player::PortableSaveKind::import_file;return true;}
  bool begin_export(uint64_t id,const fs::path& file) override{if(!begin_import(id))return false;kind=raising_player::PortableSaveKind::export_file;std::ifstream in(file,std::ios::binary);exported.assign(std::istreambuf_iterator<char>(in),{});return true;}
  std::optional<raising_player::PortableSaveResult> poll() override{if(results.empty())return {};auto result=results.front();results.pop_front();return result;}
  void cancel(uint64_t id) override{if(active&&id==request){active=false;results.push_back({id,kind,raising_player::PortableSaveStatus::cancelled,{},{},"Backup"});}}
  void shutdown() override{active=false;results.clear();}
  void complete(const std::string& bytes,uint64_t id=0){
    raising_player::PortableSaveResult result;result.requestId=id?id:request;result.kind=kind;result.status=raising_player::PortableSaveStatus::chosen;result.displayName="旅の記録 · raising.json";
    if(kind==raising_player::PortableSaveKind::import_file){result.file=raising_player::PortableSaveStagedFile::create(root,"fixture-"+std::to_string(++serial));std::ofstream file(result.file->path,std::ios::binary);file.write(bytes.data(),std::streamsize(bytes.size()));}
    active=false;results.push_back(result);
  }
};
static void expect(bool ok,const std::string& message){if(!ok)throw std::runtime_error(message);}
static std::map<std::string,std::string> record_bytes(const fs::path& save){std::map<std::string,std::string> result;const auto dir=slot_directory(save);if(fs::exists(dir))for(const auto& file:fs::directory_iterator(dir))if(file.is_regular_file()){std::ifstream in(file.path(),std::ios::binary);result[file.path().filename().generic_u8string()]=std::string(std::istreambuf_iterator<char>(in),{});}return result;}
static std::string bytes(const fs::path& path){std::ifstream stream(path,std::ios::binary);return std::string(std::istreambuf_iterator<char>(stream),{});}
